// lat/lon: degrees * 1e7 as fixed-point (signed, two's complement in a uint32_t).
// Returns the feature index containing the point for the given kind, or -1.
static inline int tgeo_find(uint8_t kind, uint32_t lat, uint32_t lon) {
  int32_t dx = (int32_t)lon - TGEO_LON0F, dy = (int32_t)lat - TGEO_LAT0F;
  if (dx < 0 || dy < 0) return -1;
  int32_t px = dx / TGEO_DXF, py = dy / TGEO_DYF;
  if (px > TGEO_MAXX || py > TGEO_MAXY) return -1;
  uint16_t i = kind ? TGEO_N_NBHD : 0, end = kind ? TGEO_N_FEATS : TGEO_N_NBHD;
  for (; i < end; i++) {
    const tgeo_feat *f = &TGEO_FEATS[i];
    if (px < f->xmin || px > f->xmax || py < f->ymin || py > f->ymax) continue;
    const int8_t *d = &TGEO_DELTAS[f->doff];
    bool inside = false;
    for (uint16_t r = 0; r < f->n_rings; r++) {
      const tgeo_ring *rg = &TGEO_RINGS[f->first_ring + r];
      int32_t x0 = rg->x0, y0 = rg->y0, ax = x0, ay = y0, bx, by;
      for (uint16_t j = 0; j < rg->n; j++) {
        if (j + 1 < rg->n) { bx = ax + d[0]; by = ay + d[1]; d += 2; }
        else { bx = x0; by = y0; }
        if ((ay > py) != (by > py) && px < ax + (bx - ax) * (py - ay) / (by - ay))
          inside = !inside;
        ax = bx; ay = by;
      }
    }
    if (inside) return i;
  }
  return -1;
}
static inline const char *tgeo_name(int i) { return TGEO_NAMES + TGEO_FEATS[i].name_off; }
